<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\Api\{HealthController,AuthController,ResourceController};
Route::get('/health',HealthController::class);Route::post('/register',[AuthController::class,'register'])->middleware('throttle:10,1');Route::post('/login',[AuthController::class,'login'])->middleware('throttle:10,1');
Route::middleware('auth:sanctum')->group(function(){Route::get('/user',[AuthController::class,'user']);Route::post('/logout',[AuthController::class,'logout']);Route::get('/dashboard',[ResourceController::class,'dashboard']);Route::get('/{resource}',[ResourceController::class,'index'])->whereIn('resource',['pets','services','appointments','medical-records','vaccinations','owners']);Route::post('/{resource}',[ResourceController::class,'store'])->whereIn('resource',['pets','services','appointments','medical-records','vaccinations','owners']);Route::get('/{resource}/{id}',[ResourceController::class,'show'])->whereIn('resource',['pets','services','appointments','medical-records','vaccinations','owners'])->whereNumber('id');Route::put('/{resource}/{id}',[ResourceController::class,'update'])->whereIn('resource',['pets','services','appointments','medical-records','vaccinations','owners'])->whereNumber('id');Route::delete('/{resource}/{id}',[ResourceController::class,'destroy'])->whereIn('resource',['pets','services','appointments','medical-records','vaccinations','owners'])->whereNumber('id');});
